    pub fn rac_device_manager_is_registered() -> rac_bool_t;
    #[doc = " @brief Clear device registration status\n\n Delegates to the set_registered callback with RAC_FALSE.\n Useful for testing or user-initiated reset."]
    pub fn rac_device_manager_clear_registration();
    #[doc = " @brief Get the current device ID\n\n Delegates to the get_device_id callback.\n\n @return Device ID string or NULL if callbacks not set"]
    pub fn rac_device_manager_get_device_id() -> *const ::std::os::raw::c_char;
