    #[doc = " @brief Purge proto download tasks that are already in a terminal state\n        (COMPLETED, FAILED, or CANCELLED) from the orchestrator's task map.\n\n The proto workflow keeps a `proto_state().tasks` entry alive for each\n started download so cancel / resume / progress_poll can find the task by\n id / model_id / resume_token even after the worker thread exits. Without\n periodic cleanup the map grows unbounded for every successful or\n cancelled download in the process lifetime. SDK callers should invoke\n this once a download terminates (e.g. after the final progress event has\n been delivered to the consumer) to release the proto task slot.\n\n The call is idempotent and threadsafe; it skips tasks that are still\n running (state ∈ PENDING / RESUMING / DOWNLOADING / EXTRACTING).\n\n @param out_purged_count Optional output: number of tasks erased.\n                         Pass NULL if the count is not needed.\n @return RAC_SUCCESS on success."]
    pub fn rac_download_cleanup_terminal_tasks_proto(out_purged_count: *mut usize) -> rac_result_t;
    #[doc = " @brief Find the actual model path after extraction.\n\n Consolidates duplicated Swift/Kotlin logic for scanning extracted directories:\n  - Finds .gguf, .onnx, .ort, .bin files\n  - Handles nested directories (e.g., sherpa-onnx archives with subdirectory)\n  - Handles single-file-nested pattern (model file inside one subdirectory)\n  - Returns the directory itself for directory-based models (ONNX)\n\n Uses POSIX opendir/readdir for cross-platform compatibility (iOS/Android/Linux/macOS).\n\n @param extracted_dir Directory where archive was extracted\n @param structure Archive structure hint (SINGLE_FILE_NESTED, NESTED_DIRECTORY, etc.)\n @param framework Inference framework (used to determine if directory-based)\n @param format Model format (used to determine expected file extensions)\n @param out_path Output buffer for the found model path\n @param path_size Size of output buffer\n @return RAC_SUCCESS if model path found, RAC_ERROR_NOT_FOUND if no model file found"]
    pub fn rac_find_model_path_after_extraction(
        extracted_dir: *const ::std::os::raw::c_char,
        structure: rac_archive_structure_t,
        framework: rac_inference_framework_t,
        format: rac_model_format_t,
        out_path: *mut ::std::os::raw::c_char,
        path_size: usize,
    ) -> rac_result_t;
    #[doc = " @brief Compute the download destination path for a model.\n\n If extraction is needed: returns a temp path in the downloads directory.\n If no extraction: returns the final model folder path.\n\n @param model_id Model identifier\n @param download_url URL to download (used for archive detection and extension)\n @param framework Inference framework\n @param format Model format\n @param out_path Output buffer for destination path\n @param path_size Size of output buffer\n @param out_needs_extraction Output: RAC_TRUE if download needs extraction\n @return RAC_SUCCESS or error code"]
    pub fn rac_download_compute_destination(
        model_id: *const ::std::os::raw::c_char,
        download_url: *const ::std::os::raw::c_char,
        framework: rac_inference_framework_t,
        format: rac_model_format_t,
        out_path: *mut ::std::os::raw::c_char,
        path_size: usize,
        out_needs_extraction: *mut rac_bool_t,
    ) -> rac_result_t;
    #[doc = " @brief Check if a download URL requires extraction.\n\n Convenience wrapper around rac_archive_type_from_path().\n\n @param download_url URL to check\n @return RAC_TRUE if URL points to an archive that needs extraction"]
    pub fn rac_download_requires_extraction(
        download_url: *const ::std::os::raw::c_char,
    ) -> rac_bool_t;
    #[doc = " @brief Canonical download completion percent for UI / SDK events.\n\n Prefer DownloadProgress.overall_progress (0.0..1.0) whenever it is finite\n and in range — commons already accounts for multi-file plans. Fall back to\n the byte ratio only when overall_progress is unusable (NaN / out of range).\n Never invent a percent when both inputs are unknown; returns 0.\n\n Result is clamped to [0, 100]. Platforms must not re-derive this with an\n inverted preference (bytes-first) or a local bytes_downloaded/total_bytes\n division when overall_progress is present."]
    pub fn rac_download_progress_percent(
        overall_progress: f32,
        bytes_downloaded: i64,
        total_bytes: i64,
    ) -> i32;
    #[doc = " @brief Subscribe to serialized runanywhere.v1.SDKEvent bytes.\n\n @return Subscription id, or 0 when callback is NULL."]
    pub fn rac_sdk_event_subscribe(
        callback: rac_sdk_event_callback_fn,
        user_data: *mut ::std::os::raw::c_void,
    ) -> u64;
    pub fn rac_sdk_event_unsubscribe(subscription_id: u64);
    #[doc = " @brief Spin-wait until all in-flight rac_sdk_event_publish_proto callbacks\n        on other threads have returned. Mirrors rac_vad_proto_quiesce /\n        rac_llm_proto_quiesce.\n\n @details rac_sdk_event_publish_proto snapshots the subscription list under\n          its internal mutex, releases the mutex, then invokes each\n          subscriber callback. rac_sdk_event_unsubscribe flips the\n          subscription's alive flag, but the publisher may already have\n          passed that check and be about to dereference the callback. SDKs\n          that free the host object backing @p user_data on unsubscribe\n          (Swift Unmanaged.release, Kotlin DeleteGlobalRef, Flutter/RN\n          equivalents) MUST quiesce to avoid a use-after-free:\n            (a) rac_sdk_event_unsubscribe(id) — no NEW dispatch sees alive;\n            (b) rac_sdk_event_quiesce()        — wait out in-flight callbacks;\n            (c) free the host object / user_data.\n          Safe to call from any thread, including reentrantly from a\n          subscriber callback. A reentrant call excludes the calling\n          thread's active dispatch frames while still waiting for callbacks\n          on every other thread."]
    pub fn rac_sdk_event_quiesce();
    #[doc = " @brief Publish serialized runanywhere.v1.SDKEvent bytes.\n\n The bytes are copied into the internal poll queue before callbacks run.\n Subscribe-callbacks are invoked synchronously on the calling thread before\n this returns; subscriber latency is publisher latency, so callbacks MUST be\n non-blocking (see the file-level threading contract above)."]
    pub fn rac_sdk_event_publish_proto(proto_bytes: *const u8, proto_size: usize) -> rac_result_t;
    #[doc = " @brief Poll the next queued SDKEvent.\n\n On success, out_event owns the returned data and must be freed with\n rac_proto_buffer_free(). Returns RAC_ERROR_NOT_FOUND when the queue is empty."]
    pub fn rac_sdk_event_poll(out_event: *mut rac_proto_buffer_t) -> rac_result_t;
    #[doc = " @brief Publish a canonical failure event."]
    pub fn rac_sdk_event_publish_failure(
        error_code: rac_result_t,
        message: *const ::std::os::raw::c_char,
        component: *const ::std::os::raw::c_char,
        operation: *const ::std::os::raw::c_char,
        recoverable: rac_bool_t,
    ) -> rac_result_t;
    #[doc = " @brief Test helper: clear queued events without changing subscriptions."]
    pub fn rac_sdk_event_clear_queue();
    #[doc = " @brief Register the telemetry sink for the canonical event destination router.\n\n The destination router (invoked from every rac::events::publish) forwards any\n event whose envelope `destination` includes the TELEMETRY bit to this\n telemetry manager via rac_telemetry_manager_track_proto. Pass the\n rac_telemetry_manager_t* handle as an opaque pointer (NULL to detach).\n\n This replaces the legacy rac_analytics_events_set_callback round-trip: SDKs\n register the telemetry manager once and the router feeds it directly from the\n proto event stream. Detaching with NULL is quiescent: it blocks new router /\n flush leases and returns only after every in-flight use of the old borrowed\n manager has completed, so the caller may destroy that manager immediately."]
    pub fn rac_events_set_telemetry_sink(telemetry_manager: *mut ::std::os::raw::c_void);
    #[doc = " @brief Flush the currently registered telemetry sink.\n\n Phase-2 SDK initialization uses this to drain telemetry through the same\n manager that the destination router already feeds. Returns\n RAC_ERROR_FEATURE_NOT_AVAILABLE when no telemetry sink is registered."]
    pub fn rac_events_flush_telemetry_sink() -> rac_result_t;
    #[doc = " @brief Create a client instance. The handle preserves the stable ABI\n and routes requests through the registered transport adapter.\n\n @param out Handle out parameter (NULL on failure).\n @return RAC_SUCCESS on success, RAC_ERROR_OUT_OF_MEMORY /\n         RAC_ERROR_INTERNAL on failure."]
    pub fn rac_http_client_create(out: *mut *mut rac_http_client_t) -> rac_result_t;
    #[doc = " @brief Destroy a client instance. NULL-safe."]
    pub fn rac_http_client_destroy(c: *mut rac_http_client_t);
    #[doc = " @brief Send a blocking request, buffer full body into `out_resp`.\n\n On success the response body lives in `out_resp->body_bytes` (size\n `body_len`). The caller MUST call `rac_http_response_free(out_resp)`\n to release the body + headers + redirected_url allocations.\n\n @return RAC_SUCCESS on any HTTP response (even 4xx/5xx — check\n         `out_resp->status`). Network / connect / TLS errors return\n         RAC_ERROR_NETWORK_ERROR. Timeout returns RAC_ERROR_TIMEOUT.\n         Cancellation only applies to the streaming variants."]
    pub fn rac_http_request_send(
        c: *mut rac_http_client_t,
        req: *const rac_http_request_t,
        out_resp: *mut rac_http_response_t,
    ) -> rac_result_t;
    #[doc = " @brief Stream body through `cb` as chunks arrive. The response\n struct is populated with status/headers only — `body_bytes` stays\n NULL; the body never lands in memory.\n\n Return `RAC_FALSE` from `cb` to cancel the transfer — the\n connection is aborted and RAC_ERROR_CANCELLED is returned."]
    pub fn rac_http_request_stream(
        c: *mut rac_http_client_t,
        req: *const rac_http_request_t,
        cb: rac_http_body_chunk_fn,
        user_data: *mut ::std::os::raw::c_void,
        out_resp_meta: *mut rac_http_response_t,
    ) -> rac_result_t;
    #[doc = " @brief Resume a download from `resume_from_byte` using\n `Range: bytes=N-`. Semantically identical to\n `rac_http_request_stream`, except the caller must already have the\n first `resume_from_byte` bytes on disk.\n\n The registered adapter receives `resume_from_byte` and must attach a\n correctly-formed `Range: bytes=N-` request. If the server returns\n 200 instead of 206, the caller can detect this via\n `out_resp_meta->status` and truncate its destination file before\n writing the new bytes."]
    pub fn rac_http_request_resume(
        c: *mut rac_http_client_t,
        req: *const rac_http_request_t,
        resume_from_byte: u64,
        cb: rac_http_body_chunk_fn,
        user_data: *mut ::std::os::raw::c_void,
        out_resp_meta: *mut rac_http_response_t,
    ) -> rac_result_t;
    #[doc = " @brief Free a response struct. NULL-safe. Frees `body_bytes`,\n every `headers[i].name` / `headers[i].value`, the outer `headers`\n array, and `redirected_url`. Does NOT free the struct itself\n (callers typically stack-allocate)."]
    pub fn rac_http_response_free(resp: *mut rac_http_response_t);
    #[doc = " @brief Returns commons' canonical default header list.\n\n Mirrors the per-SDK `defaultHeaders` block (Swift's\n `HTTPClientAdapter.defaultHeaders`, Kotlin's CppBridgeTelemetry, etc.) so\n every transport converges on the same wire shape:\n\n   - \"X-SDK-Client\": \"RunAnywhereSDK\"\n   - \"X-SDK-Version\": rac_get_version().string\n   - \"Content-Type\":  \"application/json\"\n   - \"Accept\":        \"application/json\"\n\n The \"X-Platform\" header is intentionally NOT included — its value\n (\"ios\" / \"macos\" / \"android\" / \"jvm\" / \"web\") is platform-specific and\n must be supplied per-request by the calling SDK.\n\n The returned pointer is to a static array owned by commons; do NOT free\n it. Multiple calls return the same pointer (suitable for pointer-equality\n checks in tests). Both header strings are statically allocated with\n static-storage-duration lifetimes.\n\n @param out_kvs   Receives a pointer to the static `rac_http_header_kv_t`\n                  array. Must be non-NULL.\n @param out_count Receives the number of entries in the array. Must be\n                  non-NULL.\n @return RAC_SUCCESS on success, RAC_ERROR_INVALID_ARGUMENT if either\n         out-pointer is NULL."]
    pub fn rac_http_default_headers(
        out_kvs: *mut *const rac_http_header_kv_t,
        out_count: *mut usize,
    ) -> rac_result_t;
    #[doc = " @brief Sets the process-wide Hugging Face token used to authenticate\n        gated/private-repo requests (model downloads, HEAD size preflight,\n        resumable transfers, and the HF Hub tree API used by repo\n        registration).\n\n When set, the dispatch layer attaches `Authorization: Bearer <token>`\n ONLY to https requests whose host is exactly `huggingface.co` or `hf.co`\n (never subdomains/CDN hosts) and never overrides a caller-supplied\n Authorization header. The token is never logged.\n\n When unset, the `HF_TOKEN` environment variable (captured on first use)\n acts as the fallback, so a plain env var works with no call-site change.\n Passing an empty string clears the token and disables the env fallback\n (public no-auth behavior); passing NULL resets to the default\n env-fallback state. Thread-safe; subsequent requests pick up the new\n value."]
    pub fn rac_http_hf_token_set(token: *const ::std::os::raw::c_char);
    #[doc = " @brief Returns whether a non-empty Hugging Face token is currently active.\n\n This uses the same explicit-token / `HF_TOKEN` fallback resolution as the\n request dispatcher. It lets native catalog policy skip known private repos\n before any network request without exposing the token itself."]
    pub fn rac_http_hf_token_is_configured() -> rac_bool_t;
    #[doc = " @brief Register a platform HTTP transport.\n\n Installs `ops` / `user_data` as the active transport. Subsequent\n `rac_http_request_*` calls are routed through the adapter. A\n previously-registered adapter's `destroy` callback is invoked (if\n any) before the new one is installed.\n\n Pass `ops == NULL` to unregister the current adapter. Subsequent\n HTTP calls fail with `RAC_ERROR_FEATURE_NOT_AVAILABLE` until another\n adapter is registered.\n\n Should be called before the first HTTP request for reliable\n ordering. The `ops` struct must remain valid for the lifetime of\n the registration; adapters typically use a static/global ops struct.\n\n @param ops        Vtable pointer (NULL unregisters).\n @param user_data  Opaque context passed to every callback\n                   (and freed via `ops->destroy` at the end).\n @return RAC_SUCCESS on success; an error from `ops->init` if the\n         adapter failed to initialize (in which case nothing is\n         registered)."]
    pub fn rac_http_transport_register(
        ops: *const rac_http_transport_ops_t,
        user_data: *mut ::std::os::raw::c_void,
    ) -> rac_result_t;
    #[doc = " @brief Query whether a platform HTTP transport is currently registered.\n\n @return RAC_TRUE if an adapter is installed, RAC_FALSE if the router\n         is empty."]
    pub fn rac_http_transport_is_registered() -> rac_bool_t;
    #[doc = " @brief Set the base directory for model storage.\n\n This must be called before using any path utilities.\n On iOS, this would typically be the Documents directory.\n The Swift platform adapter should call this during initialization.\n\n @param base_dir Base directory path (e.g.,\n \"/var/mobile/Containers/Data/Application/.../Documents\")\n @return RAC_SUCCESS or error code"]
    pub fn rac_model_paths_set_base_dir(base_dir: *const ::std::os::raw::c_char) -> rac_result_t;
